package br.com.felipe.termometro.lancamentoplanejado.application.api;
import br.com.felipe.termometro.lancamentoplanejado.application.api.request.*;import br.com.felipe.termometro.lancamentoplanejado.application.api.response.*;import br.com.felipe.termometro.lancamentoplanejado.application.service.*;import java.util.*;import lombok.*;import org.springframework.web.bind.annotation.*;
@RestController @RequiredArgsConstructor public class LancamentoPlanejadoRestController implements LancamentoPlanejadoAPI {private final LancamentoPlanejadoApplicationService service;public List<LancamentoPlanejadoResponse> lista(){return service.listaPendentes().stream().map(LancamentoPlanejadoResponse::new).toList();}public LancamentoPlanejadoResponse salva(UUID id,LancamentoPlanejadoRequest request){return new LancamentoPlanejadoResponse(service.salva(request.paraDominio(id)));}public LancamentoPlanejadoResponse liquidar(UUID id){return new LancamentoPlanejadoResponse(service.liquidar(id));}public LancamentoPlanejadoResponse reabrir(UUID id){return new LancamentoPlanejadoResponse(service.reabrir(id));}public LancamentoPlanejadoResponse cancelar(UUID id){return new LancamentoPlanejadoResponse(service.cancelar(id));}public void remove(UUID id){service.remove(id);}}
